import * as THREE from 'three/webgpu';
import {
  color,
  mix,
  uv,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Group container
  const group = new THREE.Object3D();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // ----- Panel -------------------------------------------------------------
  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const panelGeom = new THREE.PlaneGeometry(PANEL_W, PANEL_H);
  const panelMat = new THREE.MeshStandardNodeMaterial();

  // Vertical engineered gradient
  const uvNode = uv();
  const topColor = color('#1a1a22');
  const botColor = color('#111116');
  panelMat.colorNode = mix(topColor, botColor, uvNode.y);
  panelMat.roughnessNode = float(0.6);
  panelMat.metalnessNode = float(0.2);
  panelMat.clearcoatNode = float(0.1);
  panelMat.transparent = true; // needed for fade‑up opacity

  const panelMesh = new THREE.Mesh(panelGeom, panelMat);
  panelMesh.position.set(0, 0, 0);
  group.add(panelMesh);

  // ----- Quote Mark --------------------------------------------------------
  const QUOTE_MARK = '“'; // Lora heavy quotation mark
  const markMesh = ctx.fontAtlas.createTextMesh({
    text: QUOTE_MARK,
    family: 'Lora',
    fontSize: 62,
    fontWeight: 600,
    letterSpacing: 0,
    lineHeight: 1,
    color: '#ff2a38',
  });

  // Desired visual height for the mark
  const MARK_DESIRED_H = 0.62;
  const markBox = new THREE.Box3().setFromObject(markMesh);
  const markCurrentH = markBox.max.y - markBox.min.y || 1;
  const markScale = MARK_DESIRED_H / markCurrentH;
  markMesh.scale.setScalar(markScale);
  // Extrude depth approximation (push forward)
  markMesh.position.set(
    -PANEL_W / 2 + 0.5,
    PANEL_H / 2 - 0.5 - MARK_DESIRED_H / 2,
    0.02
  );
  group.add(markMesh);

  // ----- Quote Text --------------------------------------------------------
  const QUOTE_TEXT =
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const quoteMesh = ctx.fontAtlas.createTextMesh({
    text: QUOTE_TEXT,
    family: 'Lora',
    fontSize: 20,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.45,
    color: '#e8ecf2',
  });

  const QUOTE_Y =
    PANEL_H / 2 - 0.5 - MARK_DESIRED_H - 0.25; // 0.25 units below the mark
  quoteMesh.position.set(-PANEL_W / 2 + 0.5, QUOTE_Y, 0.03);
  group.add(quoteMesh);

  // ----- Attribution --------------------------------------------------------
  const ATTR_TEXT = 'M. OKAFOR';
  const attrMesh = ctx.fontAtlas.createTextMesh({
    text: ATTR_TEXT,
    family: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: '#e8ecf2',
  });

  const ATTR_Y = QUOTE_Y - 0.25;
  // Accent rule (thin rectangle) positioned before the attribution
  const RULE_W = 0.2;
  const RULE_H = 0.02;
  const ruleGeom = new THREE.PlaneGeometry(RULE_W, RULE_H);
  const ruleMat = new THREE.MeshStandardNodeMaterial();
  ruleMat.emissiveNode = color('#ff2a38');
  ruleMat.emissiveIntensity = 1.4;
  const ruleMesh = new THREE.Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-PANEL_W / 2 + 0.5 + RULE_W / 2, ATTR_Y, 0.03);
  group.add(ruleMesh);

  // Attribution text placed after the rule
  attrMesh.position.set(
    -PANEL_W / 2 + 0.5 + RULE_W + 0.01,
    ATTR_Y,
    0.03
  );
  group.add(attrMesh);

  // ----- Caption ------------------------------------------------------------
  const CAPTION_TEXT = 'COLLECTOR SINCE 2019';
  const captionMesh = ctx.fontAtlas.createTextMesh({
    text: CAPTION_TEXT,
    family: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
  });

  const CAPTION_Y = ATTR_Y - 0.2;
  captionMesh.position.set(-PANEL_W / 2 + 0.5, CAPTION_Y, 0.03);
  group.add(captionMesh);

  // ----- Animations ---------------------------------------------------------
  const panelTL = gsap.timeline({ paused: true });
  panelTL.from(
    panelMesh.position,
    {
      y: 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }
  );
  panelTL.from(
    panelMesh.material,
    {
      opacity: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    '<'
  );

  const markTL = gsap.timeline({ paused: true });
  markTL.fromTo(
    markMesh.scale,
    { x: markScale * 1.04, y: markScale * 1.04, z: markScale * 1.04 },
    {
      x: markScale,
      y: markScale,
      z: markScale,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    }
  );

  panelTL.add(markTL, 0);
  panelTL
